import { afterEach, describe, expect, it, vi } from 'vitest'
import { syllablesShown, type Table } from './pinyin'

/** The table's shapes, a few keys (the real one is `ui/public/chinese/pinyin.json`, generated by
 * `tools/chinese/build_pinyin_table.py`). */
const table: Table = {
  chars: { ni: '你呢', hao: '好号', shi: '是事' },
  words: { nihao: ['你好'] },
}

/** A field of the cabin's own (its text is ours to read and write), as Maps' search box is. */
function cabinField() {
  const text = { value: '' }
  return {
    id: 'cabin',
    returnKind: 'search' as const,
    read: () => text.value,
    write: (written: string) => {
      text.value = written
    },
    submit: vi.fn(),
    text,
  }
}

/** A web page's own field: the host types the player's keys into it, and the cabin's keyboard writes it whole
 * (`playerTypes: false`, webapp.ts). */
function pageField() {
  return { ...cabinField(), id: 'webapp', playerTypes: false }
}

afterEach(() => {
  vi.unstubAllGlobals()
  vi.resetModules()
})

/** The keyboard store, its table's fetch stubbed: what the store is, whether the page runs in the host, and
 * what it posted there. */
async function keyboard({ host = false, table: offered = table } = {}) {
  const posted: unknown[] = []
  if (host) {
    vi.stubGlobal('window', { chrome: { webview: { postMessage: (message: unknown) => posted.push(message) } } })
  }
  vi.stubGlobal(
    'fetch',
    vi.fn(async () => ({ ok: true, json: async () => offered })),
  )
  const { useKeyboard } = await import('./store')
  // The table is fetched the first time Chinese is composed: wait for it before picking candidates.
  const settled = () => vi.waitFor(() => expect(useKeyboard.getState().table).toBeTruthy())
  return { useKeyboard, posted, settled }
}

const char = (letter: string) => ({ kind: 'char', char: letter }) as const

describe("the cabin's own Chinese input method", () => {
  it('composes pinyin on the cabin keyboard, and writes the word the space bar picks', async () => {
    const { useKeyboard, settled } = await keyboard()
    const field = cabinField()
    useKeyboard.getState().attach(field, 'zh')
    for (const letter of 'nihao') useKeyboard.getState().press(char(letter))

    // The letters are the composition's, not the field's, and the bar reads them syllable by syllable.
    expect(useKeyboard.getState().composing).toBe('nihao')
    expect(field.text.value).toBe('')
    await settled()
    expect(syllablesShown('nihao', table)).toBe('ni hao')

    useKeyboard.getState().press({ kind: 'space' })
    expect(field.text.value).toBe('你好')
    expect(useKeyboard.getState().composing).toBe('')
  })

  it('writes one character at a time when the candidates are picked by hand', async () => {
    const { useKeyboard, settled } = await keyboard()
    const field = cabinField()
    useKeyboard.getState().attach(field, 'zh')
    for (const letter of 'nihao') useKeyboard.getState().press(char(letter))
    await settled()

    // 2 is 你 (the word comes first), leaving "hao" to compose.
    useKeyboard.getState().press(char('2'))
    expect(field.text.value).toBe('你')
    expect(useKeyboard.getState().composing).toBe('hao')
    // And 1 is 好 for what's left.
    useKeyboard.getState().press(char('1'))
    expect(field.text.value).toBe('你好')
    expect(useKeyboard.getState().composing).toBe('')
  })

  it('pages through what one syllable offers, nine to a page', async () => {
    // Fourteen characters for one syllable: more than the bar holds, so a second page of five.
    const long: Table = { chars: { a: '一二三四五六七八九十甲乙丙丁' }, words: {} }
    const { useKeyboard, settled } = await keyboard({ table: long })
    const field = cabinField()
    useKeyboard.getState().attach(field, 'zh')
    useKeyboard.getState().press(char('a'))
    await settled()
    expect(useKeyboard.getState().page).toBe(0)

    // The ninth of the first page: every digit the keyboard has picks one (1 to 9).
    useKeyboard.getState().press(char('9'))
    expect(field.text.value).toBe('九')
    expect(useKeyboard.getState().composing).toBe('')

    // On to the second page: the first candidate there is the tenth character, and the digits pick from it.
    useKeyboard.getState().press(char('a'))
    useKeyboard.getState().turnPage(1)
    expect(useKeyboard.getState().page).toBe(1)
    useKeyboard.getState().press(char('1'))
    expect(field.text.value).toBe('九十')

    // Round the ends: on past the last page comes back to the first, back past the first to the last. (A fresh
    // composition: the pick above took the whole syllable.)
    useKeyboard.getState().press(char('a'))
    expect(useKeyboard.getState().page).toBe(0)
    useKeyboard.getState().turnPage(-1)
    expect(useKeyboard.getState().page).toBe(1)
    useKeyboard.getState().turnPage(1)
    expect(useKeyboard.getState().page).toBe(0)

    // The digit picks from the page shown: 5 on the second page is 丁 (九 a page, so 十 甲 乙 丙 丁).
    useKeyboard.getState().turnPage(1)
    useKeyboard.getState().press(char('5'))
    expect(field.text.value).toBe('九十丁')
    // Nothing is left to compose: one syllable took all of it.
    expect(useKeyboard.getState().composing).toBe('')
  })

  it('writes a web page’s field through the field itself, at the page’s own caret', async () => {
    // A page's own field (webapp.ts's `webAppField`): it can take text at its own caret (`Input.insertText`,
    // the way into a field the page keeps to itself — Bilibili's own components among them).
    const inserted: string[] = []
    const field = { ...pageField(), insert: (text: string) => inserted.push(text) }
    const { useKeyboard, settled } = await keyboard()
    useKeyboard.getState().attach(field, 'zh')
    for (const letter of 'nihao') useKeyboard.getState().press(char(letter))
    await settled()

    useKeyboard.getState().press({ kind: 'space' })
    expect(inserted).toEqual(['你好'])
    // Not the whole-text write: the page's own caret and its own text stay the page's.
    expect(field.text.value).toBe('')
  })

  it("composes what the player's own keyboard types, and none of it reaches the field yet", async () => {
    const { useKeyboard, settled } = await keyboard()
    const field = cabinField()
    useKeyboard.getState().attach(field, 'zh')
    useKeyboard.getState().typed({ text: 'ni' })
    useKeyboard.getState().typed({ text: 'h' })
    useKeyboard.getState().typed({ text: 'ao' })
    expect(field.text.value).toBe('')
    expect(useKeyboard.getState().composing).toBe('nihao')
    await settled()

    // Backspace takes a letter back, not a character of the field.
    useKeyboard.getState().typed({ key: 'backspace' })
    expect(useKeyboard.getState().composing).toBe('niha')
    // Enter picks (the first candidate) and then does what the return key always does.
    useKeyboard.getState().typed({ key: 'enter' })
    expect(field.text.value).toBe('你')
    expect(field.submit).toHaveBeenCalled()
  })

  it('puts the composition away with escape, and writes nothing', async () => {
    const { useKeyboard } = await keyboard()
    const field = cabinField()
    useKeyboard.getState().attach(field, 'zh')
    for (const letter of 'ni') useKeyboard.getState().press(char(letter))
    expect(useKeyboard.getState().composing).toBe('ni')
    useKeyboard.getState().typed({ key: 'escape' })
    expect(useKeyboard.getState().composing).toBe('')
    expect(field.text.value).toBe('')
    expect(useKeyboard.getState().field).not.toBeNull()
  })

  it("tells the host to keep the player's keys out of a web page's field while it composes", async () => {
    const { useKeyboard, posted } = await keyboard({ host: true })
    const field = pageField()
    useKeyboard.getState().attach(field, 'zh')
    expect(posted).toContainEqual({ type: 'ime', on: true })

    // Another language: the page's field takes the player's own keys again (its letters are the page's). The
    // globe key takes the keyboard round every language (Chinese → English → Turkish), so English is one
    // press on from Chinese — the way out of the input method — and three presses come back to it.
    useKeyboard.getState().press({ kind: 'globe' })
    expect(useKeyboard.getState().keys.language).toBe('en')
    expect(posted).toContainEqual({ type: 'ime', on: false })
    useKeyboard.getState().press({ kind: 'globe' })
    expect(useKeyboard.getState().keys.language).toBe('tr')
    useKeyboard.getState().press({ kind: 'globe' })
    expect(useKeyboard.getState().keys.language).toBe('zh')
    expect(posted).toContainEqual({ type: 'ime', on: true })
    useKeyboard.getState().press({ kind: 'globe' })
    useKeyboard.getState().press({ kind: 'globe' })
    useKeyboard.getState().typed({ text: 'a' })
    // Nothing is composed for a page's field outside Chinese: the page has the letter already.
    expect(useKeyboard.getState().composing).toBe('')
    expect(field.text.value).toBe('')
  })

  it('leaves the other languages as they were', async () => {
    const { useKeyboard } = await keyboard()
    const field = cabinField()
    useKeyboard.getState().attach(field, 'en')
    useKeyboard.getState().press(char('a'))
    expect(field.text.value).toBe('a')
    expect(useKeyboard.getState().composing).toBe('')
    useKeyboard.getState().typed({ text: 'b' })
    expect(field.text.value).toBe('ab')
  })
})
